    let epsilon = 0.01;
    let d = getDist(p);
    let dx = getDist(p + vec3<f32>(epsilon, 0.0, 0.0)) - d;
    let dy = getDist(p + vec3<f32>(0.0, epsilon, 0.0)) - d;
    let dz = getDist(p + vec3<f32>(0.0, 0.0, epsilon)) - d;
