        let cellId = floor(cellSpace);
        let warpedCenter = (cellId + vec2<f32>(0.5)) * uniforms.tileSize;
        let centerWarp = mosaicWarp(warpedCenter, uniforms.tileSize, seedF);
        let sampleGc = warpedCenter - vec2<f32>(centerWarp);
