    let coord = vec2<i32>(in.position.xy);

    let width = i32(dims.x);
    let height = i32(dims.y);

    if (width == 0 || height == 0) {
        return vec4<f32>(0.0);
    }

    let width_f = dims.x;
    let height_f = dims.y;
    let time_value = time + timeOffset;
    let speed_value = max(speed, 0.0);
    let m = i32(mode);

