    offsets[1] = vec2( 1.0, -1.0); // bottom-right
    offsets[2] = vec2(-1.0,  1.0); // top-left
    offsets[3] = vec2(-1.0,  1.0); // top-left
    offsets[4] = vec2( 1.0, -1.0); // bottom-right
